    static int average(int[] xs) {
        int sum = 0;
        for (int x : xs) {
            sum += x;
        }
        return sum / xs.length;
    }

    public static void main(String[] args) {
        int[] week = {4, 6, 8};
        int[] empty = {};
        System.out.println(average(week));
        System.out.println(average(empty));
    }
}

fix:
public class Main {
    static int average(int[] xs) {
        if (xs.length == 0) {
            return 0;
        }
        int sum = 0;
        for (int x : xs) {
            sum += x;
        }
        return sum / xs.length;
    }

    public static void main(String[] args) {
        int[] week = {4, 6, 8};
        int[] empty = {};
        System.out.println(average(week));
        System.out.println(average(empty));
    }
}

